using EngineeringUnits.Fast;
using System;

/// <summary>
/// Saturation temperature of ammonia as a function of pressure: the inverse of <see cref="SaturationPressure"/>, fitted
/// directly instead of solved. Below 2^23 Pa (8.39 MPa) the segments are 4 per octave of p; above it
/// 4 per octave of pi = 1 - p/pc down to 2^-12, so they shrink toward the critical point. Degree 6,
/// see <see cref="AncillaryTable"/>.
///
/// Max deviation: 1.2E-8 K from CoolProp, 1.3E-9 K from the EOS dome above 405 K (to 0.4 mK below Tc).
/// Below the triple-point saturation pressure Ttriple is returned; at and above the critical pressure Tc.
///
/// Generated by the psatexp harness (sfproto-results/psatexp, "gen" mode) - do not edit the table by hand.
/// Reference data: CoolProp 6.4.2dev PropsSI(T, Q) from 195.495 K to 405.0 K (5 mK steps, 0.5 mK above 400 K).
/// Above 405.0 K CoolProp's own saturation solver breaks down (non-monotonic from ~405.13 K, then garbage), so the
/// Gao et al. 2020 dome itself was followed by continuation (2x2 Newton on equal p and g, geometric steps in theta)
/// up to its critical point (Tc = 405.56 K, rhoc = 13696 mol/m3, p = 11363391.16 Pa).
/// </summary>
public static class SaturationTemperature
{
    // EOS saturation pressure at Ttriple and at the critical point (Pa)
    internal const double PressureMin = 6055.81357399642;
    internal const double PressureMax = 11363391.162815318;
    private const double InvPressureMax = 1 / PressureMax;
    private const double PressureSplit = 8388608;

    private const int ShiftLow = 50;
    private const long FirstKeyLow = 4141;
    private const int CountLow = 43;
    private const int ShiftHigh = 50;
    private const long FirstKeyHigh = 4043;
    private const int CountHigh = 42;

    public static EngineeringUnits.Fast.Temperature Temperature(Pressure p)
    {
        double pa = p.Pascal;
        pa = pa < PressureMin ? PressureMin : pa > PressureMax ? PressureMax : pa;

        double x;
        int k;
        if (pa < PressureSplit)
        {
            x = pa;
            k = AncillaryTable.Segment(x, ShiftLow, FirstKeyLow, CountLow);
        }
        else
        {
            x = Math.FusedMultiplyAdd(-pa, InvPressureMax, 1.0);
            x = x < 0 ? 0 : x;
            k = CountLow + AncillaryTable.Segment(x, ShiftHigh, FirstKeyHigh, CountHigh);
        }
        return EngineeringUnits.Fast.Temperature.FromKelvin(AncillaryTable.Polynomial(Table, k, x));
    }

